from pathlib import Path
import json,hashlib,gzip,sqlite3
N=Path.cwd(); W=N.parent.parent/'campaign-worktree'
def sha(p):
 b=p.read_bytes();return dict(bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
pins=json.loads((N/'tibetan/evidence/source-pins.json').read_text())
for k,v in pins.items():assert sha(Path(v['path']))=={z:v[z] for z in ('bytes','sha256')},k
freezes={}
for role,digest in [('tibetan','23bc3f0044a6a4d397e593d762c7e74fdd10d792391c17461468740af50bb0b7'),('english','ccbeba4eea21c4ce3c53ec0b13d40e0f58002194c1fd7bec3259cab85e002d99')]:
 p=N/role/'freeze.json';assert sha(p)['sha256']==digest
 f=json.loads(p.read_text())
 for rel,meta in f['files'].items():assert sha(p.parent/rel)==meta,(role,rel)
 freezes[role]=dict(sha256=digest,files=len(f['files']))
master=json.loads(gzip.decompress(Path(pins['master']['path']).read_bytes()));checked=0
for rel in ['tibetan/evidence/full-lexical-evidence.json','tibetan/evidence/supplemental-full-lexical-evidence.json']:
 for q in json.loads((N/rel).read_text()):
  for r in q['master_records']:assert master[r['collection']][r['index']]==r['entry'];checked+=1
for rel in ['english/evidence/master-lexical.json','english/evidence/master-followup.json']:
 for collection,records in json.loads((N/rel).read_text())['records'].items():
  for r in records:assert master[collection][r['index']]==r['record'];checked+=1
con=sqlite3.connect('file:'+pins['spine']['path']+'?mode=ro',uri=True);con.row_factory=sqlite3.Row
for row in json.loads((N/'context.json').read_text()):
 orig=dict(con.execute('select * from corpus_segments where course=? and seq=?',(row['course'],row['seq'])).fetchone())
 assert all(orig[k]==v for k,v in row.items())
queries=0
for q in json.loads((N/'tibetan/evidence/corpus-query-evidence.json').read_text()):
 rows=[dict(r) for r in con.execute(q['sql'],q['params'])];assert rows==q['rows'] and len(rows)==q['count'];queries+=1
for q in json.loads((N/'english/evidence/query-index.json').read_text()):
 data=json.loads((N/'english'/q['file']).read_text());rows=data if isinstance(data,list) else data['records'];assert [dict(r) for r in con.execute(q['sql'],q['parameters'])]==rows;queries+=1
physical=Path(pins['physical']['path']).read_bytes(); proof=json.loads((N/'root-preparation-proof.json').read_text())
for e in proof['physical_extents']:
 b=physical[e['start']:e['start']+e['bytes']];assert b.decode()==e['original_text'] and hashlib.sha256(b).hexdigest()==e['sha256']
print(json.dumps(dict(status='PASS_IDENTITY_AND_REPLAY_ONLY',source_pins=pins,proposal_freezes=freezes,complete_master_object_occurrences_verified=checked,complete_context_rows_verified=15,recorded_query_replays=queries,physical_extents_verified=6,native_generations=0,semantics='No semantic verdict supplied by these checks.'),indent=2))
